    {var s=await _repository.SnapshotAsync();Safe(s);State(s);At(s,"RF-S07.control");Require(Sources(s,"RF-QF04-R-OPTIONS","RF-QF04-R-COMMAND","RF-QF04-L-DISPATCH"),"需要实际取得方案、短指令与值守核对材料。");return await FinalReadiness.ConfirmPolicyAsync(choice,structuredAssistance);}
